import { DOCUMENT, DestroyRef, Service, inject, signal } from '@angular/core';

export interface WebMcpToolInfo {
  name: string;
  description: string;
  /** `form` = generated by Signal Forms, `manual` = declared with `declareExperimentalWebMcpTool`. */
  kind: 'form' | 'manual';
}

export type WebMcpLogStatus = 'running' | 'success' | 'error';

export interface WebMcpLogEntry {
  id: number;
  time: Date;
  tool: string;
  source: 'agent' | 'user';
  args: unknown;
  status: WebMcpLogStatus;
  result?: string;
}

const MAX_LOG_ENTRIES = 50;
const HIGHLIGHT_MS = 2500;
/** How long after a `toolactivated` event a form submission is attributed to the agent. */
const ACTIVATION_WINDOW_MS = 2000;

/**
 * Demo-only bookkeeping for WebMCP: which tools this page exposes, what the agent called
 * and which fields it changed. The actual tool registration is done by Angular.
 */
@Service()
export class WebMcpActivityService {
  private readonly document = inject(DOCUMENT);
  private readonly legacyNavigator = this.document.defaultView?.navigator as
    { modelContext?: WebMCP.ModelContext } | undefined;
  // Same lookup as Angular's `declareExperimentalWebMcpTool`: the current spec puts the API
  // on `document`, older Chrome builds exposed it on `navigator`.
  private readonly modelContext = this.document.modelContext ?? this.legacyNavigator?.modelContext;

  /** Whether the browser exposes the WebMCP API (`document.modelContext` / `navigator.modelContext`). */
  readonly supported = !!this.modelContext && typeof this.modelContext.registerTool === 'function';

  /** Where the API was found – shown in the panel to make debugging easier. */
  readonly apiLocation = this.document.modelContext
    ? 'document.modelContext'
    : this.legacyNavigator?.modelContext
      ? 'navigator.modelContext'
      : null;

  /**
   * Names of tools the browser itself reports as registered (`modelContext.getTools()`),
   * or `null` when the browser does not offer `getTools()`.
   */
  private readonly confirmedState = signal<ReadonlySet<string> | null>(null);
  readonly confirmed = this.confirmedState.asReadonly();

  private readonly failedState = signal<ReadonlyMap<string, string>>(new Map());
  /** Tools whose registration was rejected by the browser, with the error message. */
  readonly failed = this.failedState.asReadonly();

  private readonly toolsState = signal<WebMcpToolInfo[]>([]);
  private readonly logState = signal<WebMcpLogEntry[]>([]);
  private readonly highlightedState = signal<ReadonlySet<string>>(new Set());

  readonly tools = this.toolsState.asReadonly();
  readonly log = this.logState.asReadonly();
  /** Dot-separated field paths (e.g. `experience.0.position`) recently changed by the agent. */
  readonly highlighted = this.highlightedState.asReadonly();

  private nextId = 1;
  private highlightTimer: ReturnType<typeof setTimeout> | undefined;
  private lastActivation: { tool: string; at: number } | undefined;

  constructor() {
    const onActivated = (event: ToolActivatedEvent) => {
      this.lastActivation = { tool: event.toolName, at: performance.now() };
    };
    const onToolChange = () => void this.refreshConfirmed();
    this.modelContext?.addEventListener('toolactivated', onActivated);
    this.modelContext?.addEventListener('toolchange', onToolChange);
    inject(DestroyRef).onDestroy(() => {
      this.modelContext?.removeEventListener('toolactivated', onActivated);
      this.modelContext?.removeEventListener('toolchange', onToolChange);
      clearTimeout(this.highlightTimer);
    });
  }

  addTool(tool: WebMcpToolInfo): void {
    this.toolsState.update((tools) => [...tools.filter((t) => t.name !== tool.name), tool]);
  }

  /** Called once Angular's registration promise settles. */
  registrationSettled(name: string, error?: unknown): void {
    if (error !== undefined) {
      const message = error instanceof Error ? error.message : String(error);
      this.failedState.update((failed) => new Map(failed).set(name, message));
    }
    void this.refreshConfirmed();
  }

  /** Asks the browser which tools are really registered (if it supports `getTools()`). */
  async refreshConfirmed(): Promise<void> {
    if (typeof this.modelContext?.getTools !== 'function') {
      return;
    }
    try {
      const tools = await this.modelContext.getTools();
      this.confirmedState.set(new Set(tools.map((t) => t.name)));
    } catch {
      this.confirmedState.set(null);
    }
  }

  removeTool(name: string): void {
    this.toolsState.update((tools) => tools.filter((t) => t.name !== name));
  }

  /** Returns `true` if the agent has just activated the given tool (consumes the activation). */
  consumeActivation(tool: string): boolean {
    const activation = this.lastActivation;
    const recent =
      activation?.tool === tool && performance.now() - activation.at < ACTIVATION_WINDOW_MS;
    if (recent) {
      this.lastActivation = undefined;
    }
    return recent;
  }

  start(tool: string, args: unknown, source: WebMcpLogEntry['source'] = 'agent'): number {
    const entry: WebMcpLogEntry = {
      id: this.nextId++,
      time: new Date(),
      tool,
      source,
      args,
      status: 'running',
    };
    this.logState.update((log) => [entry, ...log].slice(0, MAX_LOG_ENTRIES));
    return entry.id;
  }

  finish(id: number, status: Exclude<WebMcpLogStatus, 'running'>, result: unknown): void {
    const text = resultToText(result);
    this.logState.update((log) =>
      log.map((entry) => (entry.id === id ? { ...entry, status, result: text } : entry)),
    );
  }

  clearLog(): void {
    this.logState.set([]);
  }

  highlight(paths: readonly string[]): void {
    clearTimeout(this.highlightTimer);
    this.highlightedState.set(new Set(paths));
    this.highlightTimer = setTimeout(() => this.highlightedState.set(new Set()), HIGHLIGHT_MS);
  }
}

/** Extracts the text parts of an MCP tool result (`{content: [{type: 'text', text}]}`). */
function resultToText(result: unknown): string {
  if (typeof result === 'string') {
    return result;
  }
  if (result instanceof Error) {
    return result.message;
  }
  const content = (result as { content?: unknown } | null)?.content;
  if (Array.isArray(content)) {
    return content
      .map((part: { type?: string; text?: string }) => (part.type === 'text' ? part.text : ''))
      .join('\n');
  }
  return JSON.stringify(result, null, 2) ?? '';
}
